t/iced live.", "bean_origin": "Ethiopia", "tasting_notes": null}, {"roaster_slug": "windrose-coffee", "country_slug": "oman", "name": "Brazil Fazenda Samambaia – Pulped Natural", "slug": "brazil-fazenda-samambaia-pulped-natural", "origin_country": "Brazil", "region": null, "producer": null, "farm": null, "altitude": null, "variety": null, "process": "Natural", "roast_level": null, "flavor_notes": [], "product_url": "https://www.windrosecoffee.com/product/brazil-fazenda-samambaia", "product_image_url": "https://www.windrosecoffee.com/wp-content/uploads/2024/08/brazi-img-3.jpg", "weight_options_grams": null, "available": true, "published": true, "recommended_methods": ["V60"], "recipe_slug": "windrose-coffee-brazil-fazenda-samambaia-pulped-natural-v60-hot", "recipe_title": "Brazil Fazenda Samambaia – Pulped Natural V60", "recipe_description": "BrewAtlas filter guide for Brazil Fazenda Samambaia – Pulped Natural from Brazil — customize dose, ratio, method, and hot/iced live.", "bean_origin": "Brazil", "tasting_notes": null}]$catalog$;
  item jsonb;
  v_roaster_id uuid;
  v_coffee_id uuid;
  v_country_id uuid;
  v_city_id uuid;
  v_method_id uuid;
begin
  select id into v_method_id from public.brewing_methods where slug = 'v60' limit 1;

  for item in select * from jsonb_array_elements(payload)
  loop
    select id into v_roaster_id from public.roasters where slug = item->>'roaster_slug' limit 1;
    if v_roaster_id is null then
      raise notice 'Skipping coffee % — missing roaster %', item->>'slug', item->>'roaster_slug';
      continue;
    end if;

    select id into v_country_id from public.countries where slug = item->>'country_slug' limit 1;
    select ci.id into v_city_id from public.cities ci where ci.country_id = v_country_id limit 1;

    insert into public.coffees (
      roaster_id, name, slug, farm, producer, variety, process, altitude, roast_level,
      region, flavor_notes, product_url, product_image_url, weight_options_grams,
      available, published, recommended_methods
    ) values (
      v_roaster_id,
      item->>'name',
      item->>'slug',
      nullif(item->>'farm',''),
      nullif(item->>'producer',''),
      nullif(item->>'variety',''),
      nullif(item->>'process',''),
      nullif(item->>'altitude',''),
      nullif(item->>'roast_level',''),
      nullif(item->>'region',''),
      coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(item->'flavor_notes','[]'::jsonb)) as t(x)), array[]::text[]),
      item->>'product_url',
      nullif(item->>'product_image_url',''),
      case when item->'weight_options_grams' is null or item->'weight_options_grams' = 'null'::jsonb then null
           else (select array_agg(value::int) from jsonb_array_elements_text(item->'weight_options_grams') as t(value)) end,
      coalesce((item->>'available')::boolean, true),
      coalesce((item->>'published')::boolean, true),
      coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(item->'recommended_methods','[]'::jsonb)) as t(x)), array['V60']::text[])
    )
    on conflict (roaster_id, slug) where roaster_id is not null and slug is not null do update set
      name = excluded.name,
      farm = excluded.farm,
      producer = excluded.producer,
      variety = excluded.variety,
      process = coalesce(excluded.process, public.coffees.process),
      altitude = excluded.altitude,
      roast_level = excluded.roast_level,
      region = excluded.region,
      flavor_notes = excluded.flavor_notes,
      product_url = excluded.product_url,
      product_image_url = coalesce(excluded.product_image_url, public.coffees.product_image_url),
      weight_options_grams = excluded.weight_options_grams,
      available = excluded.available,
      published = excluded.published,
      recommended_methods = excluded.recommended_methods
    returning id into v_coffee_id;

    -- Linked personalization shell recipe (no invented official brew recipe).
    insert into public.recipes (
      title, slug, description, cover_image_url, difficulty,
      tasting_notes, featured, premium_only, published, status,
      recipe_kind, verification_status, serving_style,
      roaster_id, coffee_id, country_id, city_id, brewing_method_id,
      brew_method, is_iced, rating, coffee_beans, roast_level,
      bean_origin, process, producer, variety,
      brewing_tips
    ) values (
      item->>'recipe_title',
      item->>'recipe_slug',
      item->>'recipe_description',
      nullif(item->>'product_image_url',''),
      'Intermediate',
      nullif(item->>'tasting_notes',''),
      false,
      false, true, 'published',
      'official', 'verified', 'hot',
      v_roaster_id, v_coffee_id, v_country_id, v_city_id, v_method_id,
      'V60', false,
      case when coalesce((item->>'available')::boolean, true) then 4.6 else 4.4 end,
      item->>'name',
      null,
      nullif(item->>'bean_origin',''),
      nullif(item->>'process',''),
      null,
      null,
      'Start with a standard filter dose and ratio, then personalize for your grinder.'
    )
    on conflict (slug) do update set
      title = excluded.title,
      description = excluded.description,
      cover_image_url = coalesce(excluded.cover_image_url, public.recipes.cover_image_url),
      tasting_notes = excluded.tasting_notes,
      published = excluded.published,
      status = excluded.status,
      roaster_id = excluded.roaster_id,
      coffee_id = excluded.coffee_id,
      country_id = excluded.country_id,
      coffee_beans = excluded.coffee_beans,
      bean_origin = excluded.bean_origin,
      process = excluded.process,
      updated_at = now();
  end loop;
end $$;
